def text(x, y, txt, font, fill=WHITE, anchor="lt"):
    """Draw text. Handles multiline by splitting and positioning manually."""
    if not txt:
        return
    if '\n' in txt:
        lines = txt.split('\n')
        line_heights = []
        total_h = 0
        for line in lines:
            bbox = draw.textbbox((0, 0), line, font=font)
            line_heights.append(bbox[3] - bbox[1])
            total_h += bbox[3] - bbox[1] + 4
        total_h -= 4  # Remove trailing spacing

        # Determine starting y based on vertical anchor
        if anchor.endswith('t'):
            start_y = y
        elif anchor.endswith('m'):
            start_y = y - total_h // 2
        elif anchor.endswith('b'):
            start_y = y - total_h
        else:
            start_y = y

        for i, line in enumerate(lines):
            line_y = start_y + sum(line_heights[:i]) + i * 4
            # Horizontal alignment
            ha = anchor[:2] if len(anchor) >= 2 else 'l'
            if ha == 'rt':
                ha = 'r'
            elif ha == 'mt':
                ha = 'm'
            elif ha == 'lt':
                ha = 'l'
            draw.text((x, line_y), line, fill=fill, font=font, anchor=f"{ha}t")
    else:
        draw.text((x, y), txt, fill=fill, font=font, anchor=anchor)

