# ---- Chart area fill: per-pixel gradient fill between curve and zero ----
zero_y = Y(0)
n_data = len(years)

# Precompute pixel-to-temperature mapping via linear interpolation over data points
# For each pixel column, find the interpolated smoothed temperature
def interp_temp(px):
    """Linear interpolation of smoothed temperature at a given pixel x."""
    yr = 1700 + (px - px1) / pw * 320.0
    if yr < 1700: return smoothed[0]
    if yr > 2020: return smoothed[-1]
    idx_frac = (yr - 1700) / 320.0 * (n_data - 1)
    idx = int(idx_frac)
    if idx >= n_data - 1: return smoothed[-1]
    frac = idx_frac - idx
    return smoothed[idx] * (1 - frac) + smoothed[idx + 1] * frac

def temp_color(val):
    """Map temperature anomaly to fill color."""
    frac = max(0, min(1, (val + 0.3) / 2.4))
    if frac < 0.10:
        return blend((8, 34, 66), (16, 55, 94), frac / 0.10)
    elif frac < 0.25:
        return blend((16, 55, 94), (28, 100, 135), (frac - 0.10) / 0.15)
    elif frac < 0.48:
        return blend((28, 100, 135), (165, 112, 52), (frac - 0.25) / 0.23)
    elif frac < 0.70:
        return blend((165, 112, 52), (226, 68, 40), (frac - 0.48) / 0.22)
    else:
        return blend((226, 68, 40), (240, 40, 30), min(1, (frac - 0.70) / 0.30))

# Draw fill at every 2nd pixel for performance while maintaining visual density
for px in range(int(px1), int(px2), 2):
